const KEYWORDS = ['invoice','receipt','facture','rechnung','order confirmation','payment received'];
const CUR = {'$':'USD','€':'EUR','£':'GBP'};
const num = s => { s = s.replace(/\s/g,''); const m = s.match(/^(.*?)[.,](\d{2})$/); return m ? parseFloat(m[1].replace(/[.,]/g,'') + '.' + m[2]) : parseFloat(s.replace(/[.,]/g,'')); };
const out = [];
for (const { json: e } of $input.all()) {
  const subject = e.subject || ''; const text = `${subject}\n${e.text || (e.html || '').replace(/<[^>]+>/g,' ')}`;
  const atts = (e.attachments || []).map(a => a.filename).join('; ');
  if (!KEYWORDS.some(k => `${subject} ${atts}`.toLowerCase().includes(k))) continue;
  const totals = [...text.matchAll(/(grand total|total due|amount due|total paid|amount paid|total|amount)[^0-9$€£\n]{0,25}([$€£]|USD|EUR|GBP)?\s?([0-9][0-9 .,]*[0-9])\s?([$€£]|USD|EUR|GBP)?/gi)];
  const t = totals[totals.length - 1];
  const inv = text.match(/(invoice|receipt|order|facture)\s*(?:confirmation\s*)?(?:no\.?|number|#|id)\s*[:#]?\s*([A-Z0-9][A-Z0-9\-\/]{2,})/i);
  const from = e.from?.value?.[0] || {};
  out.push({ json: {
    date: new Date(e.date || Date.now()).toISOString().slice(0, 10),
    vendor: (from.name || (from.address || '').split('@')[1] || '').replace(/\b(billing|invoices?|receipts?|orders?|no-?reply|team)\b/gi, '').trim(),
    amount: t ? num(t[3]).toFixed(2) : '',
    currency: t ? (CUR[t[2] || t[4]] || (t[2] || t[4] || '')).toUpperCase() : '',
    invoice_no: inv ? inv[2] : '', subject, from: from.address || '', attachments: atts,
  } });
}
return out;
